  }));
}, []);

const createStore = <State>(initial: State) => {
  let current = initial;
  const listeners = new Set<(s: State) => void>();
  return {
    get: () => current,
    set: (next: State) => { current = next; listeners.forEach(fn => fn(current)); },
    subscribe: (fn: (s: State) => void) => { listeners.add(fn); return () => listeners.delete(fn); }
  };
};

