enum TypingEvent {
    CharInput(char),
    SpaceAdvance,
    Backspace { is_ctrl: bool },
    RestartSprint,
}

fn handle_event(event: TypingEvent, state: &mut ArenaState) -> Option<SessionRecord> {
    match event {
        TypingEvent::CharInput(c) => state.insert_char(c),
        TypingEvent::SpaceAdvance => state.advance_word(),
        _ => None,
    }
}

use std::collections::HashMap;

pub fn extract_weak_clusters(data: &[SessionLog]) -> HashMap<String, u32> {
    data.iter().fold(HashMap::new(), |mut acc, log| {
        for (k, v) in &log.errors {
            *acc.entry(k.clone()).or_insert(0) += v;
        }
        acc
    })
}

