type SessionRecord struct {
	ID        string    `json:"id"`
	NetWPM    float64   `json:"net_wpm"`
	Accuracy  float64   `json:"accuracy"`
	Timestamp time.Time `json:"timestamp"`
}

func (s *SessionRecord) IsGodspeed() bool {
	return s.NetWPM >= 100.0 && s.Accuracy >= 98.0
}

func BroadcastTelemetry(hub *Hub, msg TelemetryMessage) error {
	select {
	case hub.broadcast <- msg:
		return nil
	case <-time.After(100 * time.Millisecond):
		return errors.New("broadcast timeout")
	}
}
